code_snippets.parse_list:
def parse_list(self, response):
    items = response.css('ul li')
    for li in items:
        detail_url = li.css('a::attr(href)').get()
        if detail_url:
            yield response.follow(detail_url, self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('li > a::text').get()
    # 解析xml文件链接
    xml_links = response.css('a[href$=".xml"]::attr(href)').getall()
    for link in xml_links:
        yield {
            'title': title,
            'xml_url': response.urljoin(link)
        }
